ALTER TABLE "facts" ADD COLUMN "observation_seq" bigint NOT NULL DEFAULT 0;
CREATE TABLE "fact_coverages" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "digest" character varying NOT NULL, "stable" jsonb NULL, "volatile" jsonb NULL, "device_fact_coverages" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "fact_coverages_devices_fact_coverages" FOREIGN KEY ("device_fact_coverages") REFERENCES "devices" ("id") ON DELETE NO ACTION);
CREATE UNIQUE INDEX "factcoverage_digest_device_fact_coverages" ON "fact_coverages" ("digest", "device_fact_coverages");
CREATE TABLE "fact_observations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "seq" bigint NOT NULL, "observed_at" timestamptz NOT NULL, "order_source" character varying NOT NULL DEFAULT '', "order_token" bigint NOT NULL DEFAULT 0, "provenance" jsonb NOT NULL, "coverage" character varying NOT NULL, "device_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "fact_observations_devices_fact_observations" FOREIGN KEY ("device_id") REFERENCES "devices" ("id") ON DELETE NO ACTION);
CREATE UNIQUE INDEX "factobservation_device_id_seq" ON "fact_observations" ("device_id", "seq");
